"""Log record data models."""

from dataclasses import dataclass
from typing import Any, Dict, List, Optional


@dataclass
class AuditLog:
    log_id: str
    created_at: int
    action: str


@dataclass
class PageResult:
    items: List[AuditLog]
    next_cursor: Optional[str]
    has_more: bool

repo_files.database.py:
"""Database mock with indexed query capabilities."""

from typing import List
from models import AuditLog


class AuditLogDB:
    def __init__(self):
        self.records: List[AuditLog] = []

    def insert_batch(self, logs: List[AuditLog]) -> None:
        self.records.extend(logs)
        # Records naturally indexed by (created_at, log_id)
        self.records.sort(key=lambda r: (r.created_at, r.log_id))

    def get_all(self) -> List[AuditLog]:
        return list(self.records)

repo_files.pagination.py:
"""Cursor pagination evaluator."""

import base64
from typing import List, Optional
from database import AuditLogDB
from models import AuditLog, PageResult


class CursorPaginator:
    def __init__(self, db: AuditLogDB):
        self.db = db

    def encode_cursor(self, ts: int, log_id: str) -> str:
        raw = f"{ts}:{log_id}"
        return base64.b64encode(raw.encode("utf-8")).decode("utf-8")

    def decode_cursor(self, cursor: str) -> tuple[int, str]:
        raw = base64.b64decode(cursor.encode("utf-8")).decode("utf-8")
        parts = raw.split(":")
        return int(parts[0]), parts[1]

    def fetch_page(self, cursor: Optional[str], limit: int = 2) -> PageResult:
        all_logs = self.db.get_all()
        filtered: List[AuditLog] = []

        if cursor:
            after_ts, after_id = self.decode_cursor(cursor)
            # BUG: Only checks r.created_at > after_ts without secondary tie-breaker ID r.log_id > after_id,
            # skipping all subsequent sibling records sharing the exact same created_at timestamp!
            filtered = [r for r in all_logs if r.created_at > after_ts]
        else:
            filtered = all_logs

        page_items = filtered[:limit]
        has_more = len(filtered) > limit
        next_cur = None
        if page_items and has_more:
            last = page_items[-1]
            next_cur = self.encode_cursor(last.created_at, last.log_id)

        return PageResult(items=page_items, next_cursor=next_cur, has_more=has_more)

