import base64
from typing import List, Optional
from database import AuditLogDB
from models import AuditLog, PageResult


class CursorPaginator:
    def __init__(self, db: AuditLogDB):
        self.db = db

    def encode_cursor(self, ts: int, log_id: str) -> str:
        raw = f"{ts}:{log_id}"
        return base64.b64encode(raw.encode("utf-8")).decode("utf-8")

    def decode_cursor(self, cursor: str) -> tuple[int, str]:
        raw = base64.b64decode(cursor.encode("utf-8")).decode("utf-8")
        parts = raw.split(":")
        return int(parts[0]), parts[1]

    def fetch_page(self, cursor: Optional[str], limit: int = 2) -> PageResult:
        all_logs = self.db.get_all()
        filtered: List[AuditLog] = []

        if cursor:
            after_ts, after_id = self.decode_cursor(cursor)
            # Filter with composite condition: created_at > after_ts OR (created_at == after_ts AND log_id > after_id)
            filtered = [
                r for r in all_logs
                if (r.created_at > after_ts) or (r.created_at == after_ts and r.log_id > after_id)
            ]
        else:
            filtered = all_logs

        page_items = filtered[:limit]
        has_more = len(filtered) > limit
        next_cur = None
        if page_items and has_more:
            last = page_items[-1]
            next_cur = self.encode_cursor(last.created_at, last.log_id)

        return PageResult(items=page_items, next_cursor=next_cur, has_more=has_more)
